      radio:'<path d="M44 42h95V31a8 8 0 0 0-8-8H52a8 8 0 0 0-8 8z" fill="none" stroke="#64716e" stroke-width="6"/><rect x="32" y="38" width="121" height="71" rx="10" fill="#a0adb2"/><rect x="38" y="44" width="109" height="59" rx="7" fill="#bcc7c6"/><rect x="46" y="53" width="58" height="42" rx="4" fill="#758488"/><path d="M52 60h46M52 66h46M52 72h46M52 78h46M52 84h46M52 90h46" stroke="#a3b3b2" stroke-width="2"/><rect x="113" y="53" width="24" height="7" rx="2" fill="#e0dcc2"/><circle cx="125" cy="78" r="12" fill="#f0edde"/><circle cx="125" cy="78" r="7" fill="#cbd0c0"/><path d="M138 38l12-24" stroke="#92a4a5" stroke-width="3"/>',
